import React, { createContext, useContext, useState } from "react";
import { Outlet, useLocation } from "react-router-dom";
import { RoutesStrings } from "../constant/constant";
import Sidebar from "./Sidebar";
import SubscriptionModal from "./SubscriptionModal";
import Topbar from "./Topbar";

interface UpgradeContextValue {
  openUpgradeModal: () => void;
}

const UpgradeContext = createContext<UpgradeContextValue>({ openUpgradeModal: () => { } });
export const useUpgradeModal = () => useContext(UpgradeContext);

const TITLES: Record<string, string> = {
  [RoutesStrings.dashboard]: "Dashboard",
  [`${RoutesStrings.dashboard}/${RoutesStrings.dashboard_links}`]: "My Links",
  [`${RoutesStrings.dashboard}/${RoutesStrings.dashboard_settings}`]: "Settings",
};

const DashboardLayout: React.FC = () => {
  const [mobileOpen, setMobileOpen] = useState<boolean>(false);
  const [showUpgrade, setShowUpgrade] = useState<boolean>(false);
  const location = useLocation();

  const title = TITLES[location.pathname] || "Dashboard";

  return (
    <UpgradeContext.Provider value={{ openUpgradeModal: () => setShowUpgrade(true) }}>
      <div style={{ minHeight: "100vh", backgroundColor: "#f5f7fb" }}>
        <Sidebar
          onUpgradeClick={() => setShowUpgrade(true)}
          mobileOpen={mobileOpen}
          onCloseMobile={() => setMobileOpen(false)}
        />
        <div className="dashboard-content d-flex flex-column" style={{ minHeight: "100vh" }}>
          <Topbar title={title} onMenuClick={() => setMobileOpen(true)} />
          <main className="flex-grow-1 p-3 p-lg-4">
            <Outlet />
          </main>
        </div>
      </div>

      <SubscriptionModal show={showUpgrade} onClose={() => setShowUpgrade(false)} />
    </UpgradeContext.Provider>
  );
};

export default DashboardLayout;
