import React from "react";
import { BrowserRouter, Navigate, Route, Routes } from "react-router-dom";
import AuthLayout from "./components/AuthLayout";
import DashboardLayout from "./components/DashboardLayout";
import PrivateRoute from "./components/PrivateRoute";
import { RoutesStrings } from "./constant/constant";
import Dashboard from "./pages/Dashboard";
import ForgotPassword from "./pages/ForgotPassword";
import Home from "./pages/Home";
import Links from "./pages/Links";
import Login from "./pages/Login";
import Register from "./pages/Register";
import ResetPassword from "./pages/ResetPassword";
import Settings from "./pages/Settings";

const App: React.FC = () => {
  return (
    <React.Fragment>
      <BrowserRouter>
        <Routes>
          <Route path={RoutesStrings.Base} element={<Home />} />

          <Route element={<AuthLayout />}>
            <Route path={RoutesStrings.login} element={<Login />} />
            <Route path={RoutesStrings.register} element={<Register />} />
            <Route path={RoutesStrings.forgotpassword} element={<ForgotPassword />} />
            <Route path={RoutesStrings.resetpassword} element={<ResetPassword />} />
          </Route>

          <Route
            path={RoutesStrings.dashboard}
            element={
              <PrivateRoute>
                <DashboardLayout />
              </PrivateRoute>
            }
          >
            <Route index element={<Dashboard />} />
            <Route path={RoutesStrings.dashboard_links} element={<Links />} />
            <Route path={RoutesStrings.dashboard_settings} element={<Settings />} />
          </Route>

          <Route path="*" element={<Navigate to="/" replace />} />
        </Routes>
      </BrowserRouter>
    </React.Fragment>
  );
};

export default App;
