import { CredentialResponse, GoogleLogin, GoogleOAuthProvider } from '@react-oauth/google';
import React, { useEffect, useState } from "react";
import { Link, useNavigate } from "react-router-dom";
import { toast } from "react-toastify";
import { RoutesStrings } from "../constant/constant";
import Messeges from "../constant/Messeges";
import { getAuth2Dot0Token, loginUser, loginWith2Dot0Auth } from "../store/slices/authSlice";
import { useAppDispatch, useAppSelector } from "../store/store";
import { formErrorT } from "../types";
import { emailValidate } from "../utility";

const Login: React.FC = (props: any) => {
  const [userfields, setUserfields] = useState({
    email: "",
    password: ""
  });
  const [formError, setFormError] = useState<formErrorT>({});
  const [showPassword, setShowPassword] = useState<boolean>(false);

  const dispatch = useAppDispatch();
  const navigate = useNavigate();
  const { loading, token, googlebtnloading, googleclienttoken } = useAppSelector((state) => state.auth);

  useEffect(() => {
    if (googleclienttoken) return;
    dispatch(getAuth2Dot0Token());
  }, [])

  useEffect(() => {
    if (token) navigate(RoutesStrings.dashboard);
  }, [token, navigate]);

  const validateInput = () => {
    let errors: formErrorT = {};
    let valid = true;

    if (!userfields.email.trim()) {
      errors.email = Messeges.v_email;
      valid = false;
    }
    else if (!emailValidate(userfields.email)) {
      errors.email = Messeges.v_email1;
      valid = false;
    }

    if (!userfields.password) {
      errors.password = Messeges.v_password;
      valid = false;
    }
    else if (userfields.password.length < 6) {
      errors.password = Messeges.v_password1;
      valid = false;
    }

    setFormError(errors);
    return valid;
  };

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault();
    if (validateInput()) {
      dispatch(loginUser({ email: userfields.email?.trim(), password: userfields.password?.trim() }))
    }
  };

  const handleLoginWithAuth2Dot0 = (e: CredentialResponse) => {
    if (!e?.credential) return;
    dispatch(loginWith2Dot0Auth({ token: e.credential }))
  }

  return (
    <div className="container">
      <div className="row justify-content-center">
        <div className="col-md-6 col-lg-5">
          <div className="card shadow-sm mt-5">
            <div className="card-body p-4">
              <h3 className="card-title text-center mb-4">Welcome back</h3>

              <form onSubmit={handleSubmit}>
                <div className="mb-3">
                  <label htmlFor="email" className="form-label">
                    Email address
                  </label>
                  <input
                    type="email"
                    id="email"
                    name="email"
                    className="form-control"
                    value={userfields.email}
                    onChange={(e) => setUserfields(pre => ({ ...pre, [e.target.name]: e.target.value }))}
                    placeholder="you@example.com"
                  />
                  <div className="text-danger">
                    {formError?.email}
                  </div>
                </div>

                <div className="mb-3">
                  <label htmlFor="password" className="form-label">
                    Password
                  </label>
                  <div className="input-group">
                    <input
                      type={showPassword ? "text" : "password"}
                      id="password"
                      name="password"
                      className="form-control"
                      value={userfields.password}
                      onChange={(e) => setUserfields(pre => ({ ...pre, [e.target.name]: e.target.value }))}
                      placeholder="••••••••"
                    />
                    <button
                      className="btn btn-outline-primary"
                      type="button"
                      id="togglePassword"
                      onClick={() => setShowPassword(!showPassword)}>
                      <i className={`bi ${showPassword ? "bi-eye-slash" : "bi-eye"}`}></i>
                    </button>
                  </div>
                  <div className="text-danger">
                    {formError?.password}
                  </div>
                </div>

                <div className="d-flex justify-content-between align-items-center mb-3">
                  <Link to={RoutesStrings.forgotpassword} className="small">
                    Forgot password?
                  </Link>
                </div>

                <button type="submit" className="btn btn-primary w-100 mb-2" disabled={loading}>
                  {loading ? "Logging in..." : "Login"}
                </button>
              </form>

              {googlebtnloading ?
                <button type="submit" className="btn btn-outline-primary w-100 mb-2" disabled={loading}>
                  {"Loading..."}
                </button>
                :
                (googleclienttoken &&
                  <GoogleOAuthProvider
                    clientId={googleclienttoken}>
                    <GoogleLogin
                      onSuccess={handleLoginWithAuth2Dot0}
                      onError={() => { toast.error(Messeges.s_wentwrong); }}
                    />
                  </GoogleOAuthProvider>)
              }

              <p className="text-center mt-3 mb-0">
                Don't have an account? <Link to={RoutesStrings.register}>Sign up</Link>
              </p>
            </div>
          </div>
        </div>
      </div>
    </div>
  );
};

export default Login;
