import { createAsyncThunk, createSlice, PayloadAction } from "@reduxjs/toolkit";
import { toast } from "react-toastify";
import Path from "../../api.json";
import Messeges from "../../constant/Messeges";
import api from "../../services/api";
import { ApiErrorResponse, DashboardStats, Link } from "../../types";

interface LinkState {
  links: Link[];
  stats: DashboardStats | null;
  analytics: { link: Link; series: { date: string; clicks: number }[] } | null;
  loading: boolean;
  formloading: boolean;
  statsLoading: boolean;
}

const initialState: LinkState = {
  links: [],
  stats: null,
  analytics: null,
  loading: false,
  formloading: false,
  statsLoading: false
};

const extractError = (error: any): string => {
  const data: ApiErrorResponse | undefined = error?.response?.data;
  return data?.message || Messeges.s_wentwrong;
};

const extractErrorWithCode = (error: any): ApiErrorResponse | undefined => {
  return {
    statuscode: error?.response?.data?.statuscode || error?.response?.status,
    message: error?.response?.data?.message || Messeges.s_wentwrong
  };
};

export const fetchLinks = createAsyncThunk("links/fetchAll", async (_, { rejectWithValue }) => {
  try {
    const { data } = await api.get(Path.LINKS_API);
    return data.response as Link[] ?? [];
  } catch (error) {
    toast.error(extractError(error));
    return rejectWithValue(extractError(error));
  }
});

export const fetchStats = createAsyncThunk("links/fetchStats", async (_, { rejectWithValue }) => {
  try {
    const { data } = await api.get(Path.LINKS_STATS_API);
    return data.response as DashboardStats;
  } catch (error) {
    return rejectWithValue(extractError(error));
  }
});

export const fetchLinkAnalytics = createAsyncThunk(
  "links/fetchAnalytics",
  async (id: string, { rejectWithValue }) => {
    try {
      const { data } = await api.get(`${Path.LINKS_API}/${id}/${Path.ANALYTICS_API}`);
      return data.response as { link: Link; series: { date: string; clicks: number }[] };
    } catch (error) {
      return rejectWithValue(extractError(error));
    }
  }
);

export const createLink = createAsyncThunk(
  "links/create",
  async (
    payload: { originalUrl: string; customCode?: string; tags?: string[]; expiresAt?: string },
    { rejectWithValue }
  ) => {
    try {
      const { data } = await api.post(Path.LINKS_API, payload);
      return data.response as Link;
    } catch (error) {
      return rejectWithValue(extractErrorWithCode(error));
    }
  }
);

export const updateLink = createAsyncThunk(
  "links/update",
  async (
    payload: { id: string; isActive?: boolean; tags?: string[]; expiresAt?: string | null },
    { rejectWithValue }
  ) => {
    try {
      const { id, ...body } = payload;
      const { data } = await api.put(`${Path.LINKS_API}/${id}`, body);
      return data.response as Link;
    } catch (error) {
      return rejectWithValue(extractError(error));
    }
  }
);

export const deleteLink = createAsyncThunk(
  "links/delete",
  async (id: string, { rejectWithValue }) => {
    try {
      await api.delete(`${Path.LINKS_API}/${id}`);
      return id;
    } catch (error) {
      toast.error(extractError(error));
      return rejectWithValue(extractError(error));
    }
  }
);

const linkSlice = createSlice({
  name: "links",
  initialState,
  reducers: {
    clearAnalytics: (state) => {
      state.analytics = null;
    },
  },
  extraReducers: (builder) => {
    builder
      .addCase(fetchLinks.pending, (state) => {
        state.loading = true;
      })
      .addCase(fetchLinks.fulfilled, (state, action: PayloadAction<Link[]>) => {
        state.loading = false;
        state.links = action.payload;
      })
      .addCase(fetchLinks.rejected, (state, action) => {
        state.loading = false;
      })
      .addCase(fetchStats.pending, (state) => {
        state.statsLoading = true;
      })
      .addCase(fetchStats.fulfilled, (state, action: PayloadAction<DashboardStats>) => {
        state.statsLoading = false;
        state.stats = action.payload;
      })
      .addCase(fetchStats.rejected, (state) => {
        state.statsLoading = false;
      })
      .addCase(fetchLinkAnalytics.fulfilled, (state, action) => {
        state.analytics = action.payload;
      })
      .addCase(createLink.pending, (state) => {
        state.formloading = true;
      })
      .addCase(createLink.fulfilled, (state, action: PayloadAction<Link>) => {
        state.formloading = false;
        state.links.unshift(action.payload);
      })
      .addCase(createLink.rejected, (state) => {
        state.formloading = false;
      })
      .addCase(updateLink.fulfilled, (state, action: PayloadAction<Link>) => {
        const idx = state.links.findIndex((l) => l._id === action.payload._id);
        if (idx !== -1) state.links[idx] = action.payload;
      })
      .addCase(deleteLink.fulfilled, (state, action: PayloadAction<string>) => {
        state.links = state.links.filter((link) => link._id !== action.payload);
      })
  },
});

export const { clearAnalytics } = linkSlice.actions;
export default linkSlice.reducer;
