import React, { useEffect, useState } from "react";
import { Link, useNavigate } from "react-router-dom";
import { toast } from "react-toastify";
import { RoutesStrings } from "../constant/constant";
import Messeges from "../constant/Messeges";
import { registerUser, verifyOTP } from "../store/slices/authSlice";
import { useAppDispatch, useAppSelector } from "../store/store";
import { formErrorT } from "../types";
import { digitValidate, emailValidate } from "../utility";

const Register: React.FC = (props: any) => {
  const dispatch = useAppDispatch();
  const navigate = useNavigate();
  const { loading, token } = useAppSelector((state) => state.auth);

  const [userfields, setUserfields] = useState({
    firstname: "",
    lastname: "",
    email: "",
    password: "",
    confirmPassword: "",
  });
  const [formError, setFormError] = useState<formErrorT>({});
  const [showPassword, setShowPassword] = useState<boolean>(false);
  const [showConfirmPassword, setShowConfirmPassword] = useState<boolean>(false);
  const [showOTP, setShowOTP] = useState<boolean>(false);
  const [otp, setOTP] = useState<string>("");
  const [timer, setTimer] = useState<number>(30);
  const [timerKey, setTimerKey] = useState<number>(0);
  const [canResend, setCanResend] = useState<boolean>(false);

  useEffect(() => {
    if (token) navigate(RoutesStrings.dashboard);
  }, [token, navigate]);

  useEffect(() => {
    if (!showOTP) return;

    setTimer(30);
    setCanResend(false);

    const interval = setInterval(() => {
      setTimer((prev) => {
        if (prev <= 1) {
          clearInterval(interval);
          setCanResend(true);
          return 0;
        }
        return prev - 1;
      });
    }, 1000);

    return () => clearInterval(interval);
  }, [showOTP, timerKey]);

  const validateInput = () => {
    let errors: formErrorT = {};
    let valid = true;

    if (!userfields.firstname.trim()) {
      errors.firstname = Messeges.v_firstName;
      valid = false;
    }

    if (!userfields.lastname.trim()) {
      errors.lastname = Messeges.v_lastName;
      valid = false;
    }

    if (!userfields.email.trim()) {
      errors.email = Messeges.v_email;
      valid = false;
    } else if (!emailValidate(userfields.email)) {
      errors.email = Messeges.v_email1;
      valid = false;
    }

    if (!userfields.password) {
      errors.password = Messeges.v_password;
      valid = false;
    }
    else if (userfields.password.length < 6) {
      errors.password = Messeges.v_password1;
      valid = false;
    }
    else {
      if (userfields.confirmPassword.length < 6) {
        errors.confirmPassword = Messeges.v_password1;
        valid = false;
      }

      if (userfields.confirmPassword !== userfields.password) {
        errors.confirmPassword = Messeges.v_password2;
        valid = false;
      }
    }

    setFormError(errors);

    return valid;
  };

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault();
    if (validateInput()) {
      callRegistorAPI();
    }
  };

  const callRegistorAPI = async (): Promise<void> => {
    return await dispatch(registerUser({
      email: userfields.email?.trim(),
      password: userfields.password?.trim(),
      firstname: userfields.firstname?.trim(),
      lastname: userfields.lastname?.trim()
    })).then((res: any) => {
      if (!res?.error) {
        setShowOTP(true);
      }
      else if (res?.payload?.statuscode === 409) {
        toast.error(Messeges.s_email);
      }
      else {
        toast.error(Messeges.s_wentwrong);
      }
    })
  }

  // otp methods
  const onChangeOTP = (e: React.ChangeEvent<HTMLInputElement>, index: number) => {
    const val = e.target.value;
    if (!digitValidate(val)) return;
    const otpArr = otp.split("");
    otpArr[index] = val;
    const newOtp = otpArr.join("");
    setOTP(newOtp);
    if (val && e.target.nextSibling) {
      const nextSibling = e.currentTarget.nextElementSibling as HTMLInputElement | null;
      nextSibling?.focus();
    }
  }

  const onKeyDownOTP = (e: React.KeyboardEvent<HTMLInputElement>, index: number) => {
    if (e.key === "Backspace" && !otp[index]) {
      const previousSibling = e.currentTarget.previousSibling as HTMLInputElement | null;
      previousSibling?.focus();
    }
  }

  const handleResendOTP = async () => {
    if (!canResend) return;
    await callRegistorAPI();
    setTimerKey((prev) => prev + 1);
  };

  const handleVerifyOTP = (e: React.MouseEvent<HTMLButtonElement>) => {
    e.preventDefault();
    if (otp) {
      callVerifyOTPAPI();
    }
  }

  const callVerifyOTPAPI = async (): Promise<void> => {
    return await dispatch(verifyOTP({
      email: userfields.email,
      otp: otp
    })).then((res: any) => {
      if (!res?.error) {
        navigate(RoutesStrings.login);
      }
      else {
        toast.error(Messeges.s_wentwrong);
      }
    })
  }

  // end otp methods

  return (
    <div className="container">
      <div className="row justify-content-center">
        <div className="col-md-6 col-lg-5">
          <div className="card shadow-sm mt-5">
            <div className="card-body p-4">
              <h3 className="card-title text-center mb-4">Create an account</h3>

              {!showOTP ?
                <form onSubmit={handleSubmit}>
                  <div className="mb-3">
                    <label htmlFor="name" className="form-label">
                      First name
                    </label>
                    <input
                      type="text"
                      id="firstname"
                      className="form-control"
                      value={userfields.firstname}
                      name="firstname"
                      onChange={(e) => setUserfields(pre => ({ ...pre, [e.target.name]: e.target.value }))}
                      placeholder="Jane Doe"
                    />
                    <div className="text-danger">
                      {formError?.firstname}
                    </div>
                  </div>

                  <div className="mb-3">
                    <label htmlFor="name" className="form-label">
                      Last name
                    </label>
                    <input
                      type="text"
                      id="lastname"
                      className="form-control"
                      value={userfields.lastname}
                      name="lastname"
                      onChange={(e) => setUserfields(pre => ({ ...pre, [e.target.name]: e.target.value }))}
                      placeholder="Jane Doe"
                    />
                    <div className="text-danger">
                      {formError?.lastname}
                    </div>
                  </div>

                  <div className="mb-3">
                    <label htmlFor="email" className="form-label">
                      Email address
                    </label>
                    <input
                      type="email"
                      id="email"
                      className="form-control"
                      value={userfields.email}
                      name="email"
                      onChange={(e) => setUserfields(pre => ({ ...pre, [e.target.name]: e.target.value }))}
                      placeholder="you@example.com"
                    />
                    <div className="text-danger">
                      {formError?.email}
                    </div>
                  </div>

                  <div className="mb-3">
                    <label htmlFor="password" className="form-label">
                      Password
                    </label>
                    <div className="input-group">
                      <input
                        type={showPassword ? "text" : "password"}
                        id="password"
                        className="form-control"
                        value={userfields.password}
                        name="password"
                        onChange={(e) => setUserfields(pre => ({ ...pre, [e.target.name]: e.target.value }))}
                        placeholder="At least 6 characters"
                      />
                      <button
                        className="btn btn-outline-primary"
                        type="button"
                        id="togglePassword"
                        onClick={() => setShowPassword(!showPassword)}>
                        <i className={`bi ${showPassword ? "bi-eye-slash" : "bi-eye"}`}></i>
                      </button>
                    </div>
                    <div className="text-danger">
                      {formError?.password}
                    </div>
                  </div>

                  <div className="mb-3">
                    <label htmlFor="confirmPassword" className="form-label">
                      Confirm password
                    </label>
                    <div className="input-group">
                      <input
                        type={showConfirmPassword ? "text" : "password"}
                        id="confirmPassword"
                        className="form-control"
                        value={userfields.confirmPassword}
                        name="confirmPassword"
                        onChange={(e) => setUserfields(pre => ({ ...pre, [e.target.name]: e.target.value }))}
                        placeholder="Repeat your password"
                      />
                      <button
                        className="btn btn-outline-primary"
                        type="button"
                        id="togglePassword"
                        onClick={() => setShowConfirmPassword(!showConfirmPassword)}>
                        <i className={`bi ${showConfirmPassword ? "bi-eye-slash" : "bi-eye"}`}></i>
                      </button>
                    </div>
                    <div className="text-danger">
                      {formError?.confirmPassword}
                    </div>
                  </div>

                  <button type="submit" className="btn btn-primary w-100" disabled={loading}>
                    {loading ? "Creating account..." : "Sign up"}
                  </button>

                  <p className="text-center mt-3 mb-0">
                    Already have an account? <Link to={RoutesStrings.login}>Login</Link>
                  </p>
                </form>
                :
                <div className="text-center mt-4">
                  <h5>Enter OTP</h5>

                  <div style={{ display: "flex", gap: "10px", justifyContent: "center" }}>
                    {[...Array(6)].map((_, index) => (
                      <input
                        key={index}
                        type="text"
                        maxLength={1}
                        value={otp[index] || ""}
                        onChange={(e) => onChangeOTP(e, index)}
                        onKeyDown={(e) => onKeyDownOTP(e, index)}
                        style={{
                          width: "45px",
                          height: "45px",
                          textAlign: "center",
                          fontSize: "18px",
                          border: "1px solid #ccc",
                          borderRadius: "6px",
                        }}
                      />
                    ))}
                  </div>

                  <p className="text-center mt-3 mb-0">
                    {canResend ? (
                      <a tabIndex={-1} role="button" className="text-decoration-none"
                        onClick={handleResendOTP}>
                        Resend OTP
                      </a>) :
                      (
                        <p className="text-muted">
                          Resend OTP in {timer}s
                        </p>
                      )}
                  </p>

                  <button
                    className="btn btn-primary mt-3"
                    disabled={otp.length !== 6 || loading}
                    onClick={handleVerifyOTP}
                  >
                    {loading ? "Verifying" : "Verify OTP"}
                  </button>
                </div>}

            </div>
          </div>
        </div>
      </div>
    </div>
  );
};

export default Register;
