import { createAsyncThunk, createSlice, PayloadAction } from "@reduxjs/toolkit";
import { toast } from "react-toastify";
import Path from "../../api.json";
import constant from "../../constant/constant";
import Messeges from "../../constant/Messeges";
import api from "../../services/api";
import { ApiErrorResponse, LoginResponse, User } from "../../types";
import {
  getDataFromLocalStorage, getObjectFromLocalStorage, removelocalData,
  storeDataLocalStorage,
  storeObjectLocalStorage
} from "../../utility";

interface AuthState {
  user: any;
  token: string | null;
  loading: boolean;
  googlebtnloading: boolean;
  googleclienttoken: string | null;
}

const storedUser = getObjectFromLocalStorage(constant.USERINFO);
const storedToken = getDataFromLocalStorage(constant.AUTHTHOKEN);

const initialState: AuthState = {
  user: storedUser,
  token: storedToken || null,
  loading: false,
  googlebtnloading: false,
  googleclienttoken: null
};

const extractError = (error: any): string => {
  const data: ApiErrorResponse | undefined = error?.response?.data;
  return data?.message || Messeges.s_wentwrong;
};

const extractErrorWithCode = (error: any): ApiErrorResponse | undefined => {
  return {
    statuscode: error?.response?.data?.statuscode || error?.response?.status,
    message: error?.response?.data?.message || Messeges.s_wentwrong
  };
};

export const registerUser = createAsyncThunk(
  "auth/register",
  async (
    payload: { firstname: string; lastname: string; email: string; password: string },
    { rejectWithValue }
  ) => {
    try {
      const { data } = await api.post(Path.REGISTER_API, payload);
      return data?.response;
    } catch (error) {
      return rejectWithValue(extractErrorWithCode(error));
    }
  }
);

export const verifyOTP = createAsyncThunk(
  'auth/verifyOTP',
  async (
    payload: { email: string, otp: string },
    { rejectWithValue }
  ) => {
    try {
      const { data } = await api.post(Path.VERIFYOTP_API, payload);
      return data?.response
    }
    catch (error) {
      return rejectWithValue(extractErrorWithCode(error))
    }
  }
)

export const loginUser = createAsyncThunk(
  "auth/login",
  async (payload: { email: string; password: string }, { rejectWithValue }) => {
    try {
      const { data } = await api.post(Path.LOGIN_API, payload);
      return data?.response as LoginResponse;
    } catch (error) {
      toast.error(Messeges.s_wentwrong);
      return rejectWithValue(extractError(error));
    }
  }
);

export const loginWith2Dot0Auth = createAsyncThunk(
  "auth/loginWith2Dot0Auth",
  async (payload: { token: string }, { rejectWithValue }) => {
    try {
      const { data } = await api.post(Path.LOGINWITH2DOT0TOKEN_API, payload);
      return data?.response as LoginResponse;
    }
    catch (error) {
      toast.error(Messeges.s_wentwrong);
      return rejectWithValue(extractErrorWithCode((error)))
    }
  })

export const forgotPassword = createAsyncThunk(
  "auth/forgotPassword",
  async (payload: { email: string }, { rejectWithValue }) => {
    try {
      const { data } = await api.post(Path.FORGOT_PASSWORD_API, payload);
      return data?.response;
    } catch (error) {
      return rejectWithValue(extractError(error));
    }
  }
);

export const resetPassword = createAsyncThunk(
  "auth/resetPassword",
  async (
    payload: { token: string; password: string },
    { rejectWithValue }
  ) => {
    try {
      const { data } = await api.post(

        `${Path.RESET_PASSWORD_API}/${payload.token}`,
        { password: payload.password }
      );
      return data;
    } catch (error) {
      return rejectWithValue(extractError(error));
    }
  }
);

export const getAuth2Dot0Token = createAsyncThunk(
  "auth/getAuth2Dot0Token",
  async (_, { rejectWithValue }) => {
    try {
      const { data } = await api.get(Path.GETAUTH2DOT0TOKEN_API);
      return data.response;
    }
    catch (error) {
      return rejectWithValue(extractErrorWithCode(error));
    }
  }
)

const authSlice = createSlice({
  name: "auth",
  initialState,
  reducers: {
    logout: (state) => {
      state.user = null;
      state.token = null;
      removelocalData(constant.AUTHTHOKEN);
      removelocalData(constant.USERINFO);
    },
    updateUserPlan: (state, action: PayloadAction<User["plan"]>) => {
      if (state.user) {
        state.user.plan = action.payload;
        storeObjectLocalStorage(constant.USERINFO, state.user);
      }
    },
  },
  extraReducers: (builder) => {
    builder
      // Register
      .addCase(registerUser.pending, (state) => {
        state.loading = true;
      })
      .addCase(registerUser.fulfilled, (state) => {
        state.loading = false;
      })
      .addCase(registerUser.rejected, (state) => {
        state.loading = false;
      })
      // verifyOTP
      .addCase(verifyOTP.pending, (state) => {
        state.loading = true;
      })
      .addCase(verifyOTP.fulfilled, (state) => {
        state.loading = false
      })
      .addCase(verifyOTP.rejected, (state) => {
        state.loading = false
      })
      // Login
      .addCase(loginUser.pending, (state) => {
        state.loading = true;
      })
      .addCase(loginUser.fulfilled, (state, action: PayloadAction<LoginResponse>) => {
        const { token, ...userinfo } = action.payload;
        state.loading = false;
        state.user = userinfo;
        state.token = token;
        storeDataLocalStorage(constant.AUTHTHOKEN, token)
        storeObjectLocalStorage(constant.USERINFO, userinfo);
      })
      .addCase(loginUser.rejected, (state) => {
        state.loading = false;
      })
      // Forgot password
      .addCase(forgotPassword.pending, (state) => {
        state.loading = true;
      })
      .addCase(forgotPassword.fulfilled, (state) => {
        state.loading = false;
      })
      .addCase(forgotPassword.rejected, (state) => {
        state.loading = false;
      })
      // Reset password
      .addCase(resetPassword.pending, (state) => {
        state.loading = true;
      })
      .addCase(resetPassword.fulfilled, (state) => {
        state.loading = false;
      })
      .addCase(resetPassword.rejected, (state) => {
        state.loading = false;
      })
      .addCase(getAuth2Dot0Token.pending, (state) => {
        state.googlebtnloading = true;
      })
      .addCase(getAuth2Dot0Token.fulfilled, (state, action) => {
        state.googleclienttoken = action.payload;
        state.googlebtnloading = false;
      })
      .addCase(getAuth2Dot0Token.rejected, (state) => {
        state.googlebtnloading = false;
      })
      .addCase(loginWith2Dot0Auth.pending, (state) => {
        state.googlebtnloading = true;
      })
      .addCase(loginWith2Dot0Auth.fulfilled, (state, action) => {
        const { token, ...userinfo } = action.payload;
        state.googlebtnloading = false;
        state.user = userinfo;
        state.token = token;
        storeDataLocalStorage(constant.AUTHTHOKEN, token)
        storeObjectLocalStorage(constant.USERINFO, userinfo);
      })
      .addCase(loginWith2Dot0Auth.rejected, (state) => {
        state.googlebtnloading = false;
      })
  },
});

export const { logout, updateUserPlan } = authSlice.actions;
export default authSlice.reducer;
