import React from "react";
import { NavLink } from "react-router-dom";
import { useAppSelector } from "../store/store";

interface SidebarProps {
  onUpgradeClick: () => void;
  mobileOpen: boolean;
  onCloseMobile: () => void;
}

const navItems = [
  { to: "/dashboard", icon: "bi-speedometer2", label: "Dashboard", end: true },
  { to: "/dashboard/links", icon: "bi-link-45deg", label: "My Links" },
  { to: "/dashboard/settings", icon: "bi-gear", label: "Settings" },
];

const Sidebar: React.FC<SidebarProps> = ({ onUpgradeClick, mobileOpen, onCloseMobile }) => {
  const { user } = useAppSelector((state) => state.auth);

  return (
    <>
      {mobileOpen && (
        <div
          className="d-lg-none position-fixed top-0 start-0 w-100 h-100"
          style={{ backgroundColor: "rgba(0,0,0,0.4)", zIndex: 1040 }}
          onClick={onCloseMobile}
        />
      )}
      <aside
        className={`bg-white border-end d-flex flex-column position-fixed top-0 start-0 h-100 ${
          mobileOpen ? "d-flex" : "d-none d-lg-flex"
        }`}
        style={{ width: 250, zIndex: 1045 }}
      >
        <div className="d-flex align-items-center gap-2 px-4 py-4">
          <div
            className="d-flex align-items-center justify-content-center rounded-3 bg-primary text-white fw-bold"
            style={{ width: 36, height: 36 }}
          >
            <i className="bi bi-link-45deg fs-5"></i>
          </div>
          <span className="fw-bold fs-5">LinkShort</span>
        </div>

        <nav className="flex-grow-1 px-3">
          {navItems.map((item) => (
            <NavLink
              key={item.to}
              to={item.to}
              end={item.end}
              onClick={onCloseMobile}
              className={({ isActive }) =>
                `d-flex align-items-center gap-2 px-3 py-2 mb-1 rounded-3 text-decoration-none ${
                  isActive ? "bg-primary bg-opacity-10 text-primary fw-semibold" : "text-secondary"
                }`
              }
            >
              <i className={`bi ${item.icon}`}></i>
              {item.label}
            </NavLink>
          ))}
        </nav>

        <div className="p-3">
          <div className="card border-0 bg-primary bg-opacity-10 p-3 text-center">
            <i className="bi bi-stars text-primary fs-3 mb-2"></i>
            <p className="small mb-2">
              You're on the <strong className="text-capitalize">{user?.plan || "free"}</strong> plan
            </p>
            {user?.plan !== "business" && (
              <button className="btn btn-primary btn-sm" onClick={onUpgradeClick}>
                Change plan
              </button>
            )}
          </div>
        </div>
      </aside>
    </>
  );
};

export default Sidebar;
