import React, { useEffect } from "react";
import { Area, AreaChart, CartesianGrid, ResponsiveContainer, Tooltip, XAxis, YAxis } from "recharts";
import { clearAnalytics, fetchLinkAnalytics } from "../store/slices/linkSlice";
import { useAppDispatch, useAppSelector } from "../store/store";

interface LinkAnalyticsModalProps {
  show: boolean;
  onClose: () => void;
  linkId: string | null;
}

const LinkAnalyticsModal: React.FC<LinkAnalyticsModalProps> = ({ show, onClose, linkId }) => {
  const dispatch = useAppDispatch();
  const { analytics } = useAppSelector((state) => state.links);

  useEffect(() => {
    if (show && linkId) {
      dispatch(fetchLinkAnalytics(linkId));
    }
    return () => {
      if (!show) dispatch(clearAnalytics());
    };
  }, [show, linkId, dispatch]);

  if (!show) return null;

  const formattedSeries =
    analytics?.series.map((point) => ({
      ...point,
      label: new Date(point.date).toLocaleDateString(undefined, { month: "short", day: "numeric" }),
    })) || [];

  return (
    <div
      className="modal fade show d-block"
      tabIndex={-1}
      style={{ backgroundColor: "rgba(15, 23, 42, 0.6)" }}
      onClick={(e) => {
        if (e.target === e.currentTarget) onClose();
      }}
    >
      <div className="modal-dialog modal-dialog-centered modal-lg">
        <div className="modal-content border-0 shadow-lg" style={{ borderRadius: 16 }}>
          <div className="modal-header border-0 pb-0">
            <div>
              <h5 className="modal-title fw-bold mb-1">Link analytics</h5>
              {analytics?.link && (
                <p className="text-muted small mb-0 text-break">{analytics.link.originalUrl}</p>
              )}
            </div>
            <button type="button" className="btn-close" onClick={onClose}></button>
          </div>
          <div className="modal-body pt-3">
            {!analytics ? (
              <div className="text-center py-5">
                <div className="spinner-border text-primary" role="status" />
              </div>
            ) : (
              <>
                <div className="row g-3 mb-4">
                  <div className="col-6 col-md-3">
                    <div className="p-3 bg-light rounded-3 text-center">
                      <div className="fs-4 fw-bold">{analytics.link.clicks}</div>
                      <div className="text-muted small">Total clicks</div>
                    </div>
                  </div>
                  <div className="col-6 col-md-3">
                    <div className="p-3 bg-light rounded-3 text-center">
                      <div className="fs-4 fw-bold">
                        {formattedSeries.reduce((sum, p) => sum + p.clicks, 0)}
                      </div>
                      <div className="text-muted small">Last 14 days</div>
                    </div>
                  </div>
                  <div className="col-6 col-md-3">
                    <div className="p-3 bg-light rounded-3 text-center">
                      <div className="fs-4 fw-bold text-capitalize">
                        {analytics.link.isActive ? "Active" : "Disabled"}
                      </div>
                      <div className="text-muted small">Status</div>
                    </div>
                  </div>
                  <div className="col-6 col-md-3">
                    <div className="p-3 bg-light rounded-3 text-center">
                      <div className="fs-4 fw-bold">{analytics.link.shortCode}</div>
                      <div className="text-muted small">Short code</div>
                    </div>
                  </div>
                </div>

                <ResponsiveContainer width="100%" height={260}>
                  <AreaChart data={formattedSeries}>
                    <defs>
                      <linearGradient id="analyticsColor" x1="0" y1="0" x2="0" y2="1">
                        <stop offset="5%" stopColor="#0d6efd" stopOpacity={0.35} />
                        <stop offset="95%" stopColor="#0d6efd" stopOpacity={0} />
                      </linearGradient>
                    </defs>
                    <CartesianGrid strokeDasharray="3 3" vertical={false} />
                    <XAxis dataKey="label" tick={{ fontSize: 12 }} />
                    <YAxis allowDecimals={false} tick={{ fontSize: 12 }} width={30} />
                    <Tooltip />
                    <Area
                      type="monotone"
                      dataKey="clicks"
                      stroke="#0d6efd"
                      strokeWidth={2}
                      fill="url(#analyticsColor)"
                    />
                  </AreaChart>
                </ResponsiveContainer>
              </>
            )}
          </div>
        </div>
      </div>
    </div>
  );
};

export default LinkAnalyticsModal;
