import Moment from "moment";
import React, { useEffect, useState } from "react";
import { useUpgradeModal } from "../components/DashboardLayout";
import { DateFormate, PlanTypeEnum } from "../constant/constant";
import { fetchMySubscription, fetchMyTransactions } from "../store/slices/subscriptionSlice";
import { useAppDispatch, useAppSelector } from "../store/store";
import { PLAN_ICONS } from "../utils/planIcons";

const Settings: React.FC = () => {
  const dispatch = useAppDispatch();
  const { openUpgradeModal } = useUpgradeModal();
  const { user } = useAppSelector((state) => state.auth);
  const { subscribedPlan, planRenewsAt, transactions } = useAppSelector((state) => state.subscription);
  const [copied, setCopied] = useState<boolean>(false);

  useEffect(() => {
    dispatch(fetchMySubscription());
    dispatch(fetchMyTransactions());
  }, [dispatch]);

  const initials = ((user?.firstname || user?.lastname) ? (`${user?.firstname} ${user?.lastname}`) : "U")
    .split(" ")
    .map((n) => n[0])
    .slice(0, 2)
    .join("")
    .toUpperCase();

  const handleCopyEmail = () => {
    if (!user?.firstname || !user?.lastname) return;
    navigator.clipboard.writeText((user?.firstname || user?.lastname) ? (`${user?.firstname} ${user?.lastname}`) : "");
    setCopied(true);
    setTimeout(() => setCopied(false), 1500);
  };

  return (
    <div>
      <div className="mb-4">
        <h3 className="fw-bold mb-1">Settings</h3>
        <p className="text-muted mb-0">Manage your profile and subscription.</p>
      </div>

      <div className="row g-4">
        {/* Profile card */}
        <div className="col-lg-4">
          <div className="card border-0 shadow-sm rounded-4-custom h-100">
            <div className="card-body p-4 text-center">
              <div
                className="d-inline-flex align-items-center justify-content-center rounded-circle bg-primary text-white fw-bold mb-3"
                style={{ width: 72, height: 72, fontSize: 24 }}
              >
                {initials}
              </div>
              <h5 className="fw-bold mb-1">{(user?.firstname || user?.lastname) ? (`${user?.firstname} ${user?.lastname}`) : "U"}</h5>
              {/* <button
                className="btn btn-sm btn-light text-muted d-inline-flex align-items-center gap-1"
                onClick={handleCopyEmail}
              >
                {user?.email} <i className={`bi ${copied ? "bi-check-lg text-success" : "bi-clipboard"}`}></i>
              </button> */}
            </div>
          </div>
        </div>

        {/* Plan card */}
        <div className="col-lg-8">
          <div className="card border-0 shadow-sm rounded-4-custom h-100">
            <div className="card-body p-4">
              <div className="d-flex justify-content-between align-items-start mb-3">
                <div>
                  <h6 className="fw-bold mb-1">Current subscription</h6>
                  <p className="text-muted small mb-0">
                    {subscribedPlan?.price ? "Billed monthly via Braintree" : "No payment required"}
                  </p>
                </div>
                <button className="btn btn-primary btn-sm" onClick={openUpgradeModal}>
                  {subscribedPlan?.planid === PlanTypeEnum.premium_month ? "Manage plan" : "Upgrade"}
                </button>
              </div>

              {subscribedPlan && (
                <div className="d-flex align-items-center gap-3 p-3 bg-light rounded-3 mb-3">
                  <div
                    className="d-flex align-items-center justify-content-center rounded-circle bg-primary bg-opacity-10 text-primary"
                    style={{ width: 48, height: 48 }}
                  >
                    <i className={`bi ${PLAN_ICONS[subscribedPlan.braintreePlanId]} fs-5`}></i>
                  </div>
                  <div>
                    <div className="fw-bold">{subscribedPlan.braintreePlanId} plan — ${subscribedPlan.price}/mo</div>
                    <div className="text-muted small">
                      {subscribedPlan.linkLimit === -1
                        ? "Unlimited short links"
                        : `Up to ${subscribedPlan.linkLimit} short links`}
                      {planRenewsAt && (
                        <> · Renews {new Date(planRenewsAt).toLocaleDateString()}</>
                      )}
                    </div>
                  </div>
                </div>
              )}

              <h6 className="fw-bold mt-4 mb-3">Billing history</h6>
              {transactions.length === 0 ? (
                <p className="text-muted small mb-0">No payments yet.</p>
              ) : (
                <div className="table-responsive">
                  <table className="table table-sm align-middle mb-0">
                    <thead>
                      <tr className="text-muted small">
                        <th>Date</th>
                        <th>Plan</th>
                        <th>Amount</th>
                        <th>Status</th>
                      </tr>
                    </thead>
                    <tbody>
                      {transactions.map((tx) => (
                        <tr key={tx._id}>
                          <td className="small">{Moment(tx.createdAt).format(DateFormate.YYYYMMMDDDash)}</td>
                          <td className="small text-capitalize">{tx.braintreePlanId}</td>
                          <td className="small">${tx.amount.toFixed(2)}</td>
                          <td>
                            <span className="badge bg-success bg-opacity-10 text-success text-capitalize">
                              {tx.status}
                            </span>
                          </td>
                        </tr>
                      ))}
                    </tbody>
                  </table>
                </div>
              )}
            </div>
          </div>
        </div>
      </div>
    </div>
  );
};

export default Settings;
