import axios, {
  AxiosError,
  AxiosInstance,
  InternalAxiosRequestConfig
} from "axios";
import Path from "../api.json";
import constant from "../constant/constant";
import { getDataFromLocalStorage, removelocalData, storeDataLocalStorage } from "../utility";

const api: AxiosInstance = axios.create({
  baseURL: Path.baseURL,
  withCredentials: true,
});

let accessToken: string | null = getDataFromLocalStorage(constant.AUTHTHOKEN);

// The currently running refresh request.
// All concurrent 401s wait for this promise.
let refreshPromise: Promise<string> | null = null;

export function setAccessToken(token: string | null) {
  accessToken = token;
}

api.interceptors.request.use(
  (config: InternalAxiosRequestConfig) => {
    if (accessToken) {
      config.headers.Authorization = accessToken ? `Bearer ${accessToken}` : accessToken;
    }

    return config;
  }
);

api.interceptors.response.use(
  (response) => response,

  async (error: AxiosError) => {
    const originalRequest = error.config as
      | (InternalAxiosRequestConfig & { _retry?: boolean })
      | undefined;

    if (!originalRequest) {
      return Promise.reject(error);
    }

    // Only handle access-token expiration.
    if (error.response?.status !== 401) {
      return Promise.reject(error);
    }

    // Prevent an infinite retry loop.
    if (originalRequest._retry) {
      return Promise.reject(error);
    }

    // Don't try to refresh the refresh endpoint itself.
    if (originalRequest.url?.includes(`/${Path.REFRESH_TOKEN_API}`)) {
      return Promise.reject(error);
    }

    originalRequest._retry = true;

    try {
      // If another request is already refreshing,
      // wait for that exact same promise.
      if (!refreshPromise) {
        refreshPromise = refreshAccessToken()
          .finally(() => {
            refreshPromise = null;
          });
      }

      const newToken = await refreshPromise;

      accessToken = newToken;

      originalRequest.headers.Authorization = `Bearer ${newToken}`;

      return api(originalRequest);
    } catch (refreshError) {
      accessToken = null;

      // Redirect/logout/etc.
      handleSessionExpired();

      return Promise.reject(refreshError);
    }
  }
);

async function refreshAccessToken(): Promise<string> {
  const { data } = await api.post(`/${Path.REFRESH_TOKEN_API}`);
  if (data?.response) {
    storeDataLocalStorage(constant.AUTHTHOKEN, data?.response);
  }
  else {
    removelocalData(constant.AUTHTHOKEN);
  }
  return data?.response;
}

function handleSessionExpired() {
  // Clear user state / Redux / Zustand / React Query cache etc.
  // window.location.href = "/login";
}

export default api;